    context['actual_oem_expired_meaning'] = oem_expired_meaning
    context['actual_sms_os_expired'] = sms_os_expired
    context['actual_sms_os_expired_meaning'] = sms_os_expired_meaning
    context['actual_os_load_expired'] = os_load_expired
