    context['actual_bios_post_expired'] = bios_post_expired
    context['actual_bios_post_expired_meaning'] = bios_post_expired_meaning
    context['actual_bios_frb2_expired'] = bios_frb2_expired
    context['actual_bios_frb2_expired_meaning'] = bios_frb2_expired_meaning
    context['actual_initial_countdown'] = initial_countdown
    context['actual_present_countdown'] = present_countdown
    print("\n  Decoded Response:")
